import { expect, it } from 'vitest';
import { demoBundle } from '../../src/config';
import { MultipassInterpreter } from '../../src/adapters/ai/multipass/interpreter';
import { fixture, seed } from './f02-fixtures';
import { multiResponse, scripted } from './f02-scripts';

it.each(['repair', 'context'] as const)('captures a safe diagnostic for a five-attempt %s failure', async mode => {
  const { name, messages } = fixture('C01');
  const input = { caseSnapshot: seed(name, messages), messages, factSchema: demoBundle.factSchema, agentProfile: demoBundle.agentProfile };
  const captured: unknown[] = [];
  const interpreter = new MultipassInterpreter({ execute: async request => {
    if (mode === 'repair' && (request.role === 'E1' || request.role === 'Repair')) return { secret: 'customer-and-model-output-secret' };
    if (mode === 'context' && request.role === 'S2') return { status: 'complete', reviews: [], verdicts: [] };
    return multiResponse(request.role, request.input, scripted(name, messages));
  } }, diagnostic => captured.push(diagnostic));
  const result = await interpreter.interpret(input);
  expect(result).toMatchObject({ ok: false, error: { code: 'MODEL_OUTPUT_INVALID' } });
  expect(captured).toHaveLength(1);
  expect(captured[0]).toMatchObject({ finalStatus: 'failed', failureCode: mode === 'repair' ? 'initial_pass_failed' : 'incomplete_contextual_review', consumed: 5 });
  const trace = captured[0] as { operations: { role: string; status: string; durationMs: number }[] };
  expect(trace.operations.map(operation => operation.role)).toEqual(['E1', 'E2', 'E3', 'S1', mode === 'repair' ? 'Repair' : 'S2']);
  expect(JSON.stringify(captured)).not.toContain('customer-and-model-output-secret');
  expect(JSON.stringify(captured)).not.toContain('3.800');
});

it('does not change interpretation if the diagnostic observer fails', async () => {
  const { name, messages } = fixture('C01');
  const input = { caseSnapshot: seed(name, messages), messages, factSchema: demoBundle.factSchema, agentProfile: demoBundle.agentProfile };
  const interpreter = new MultipassInterpreter({ execute: async request => multiResponse(request.role, request.input, scripted(name, messages)) }, () => { throw new Error('observer failed'); });
  expect((await interpreter.interpret(input)).ok).toBe(true);
});
import { randomUUID } from 'node:crypto';
import type { Interpreter, SubjectRef } from '../../../contracts';
import { validateInterpretation, failure } from '../validation';
import { runPipeline } from './pipeline';
import type { FakeTransport } from './scheduler';
import { PROMPT_VERSION } from './prompts';
import { validateAssertions } from '../../../domain/facts';
import type { OperationTrace } from './trace';

export type MultipassDiagnostic = {
  finalStatus: 'consolidated' | 'human_review_required' | 'failed';
  failureCode: string | null;
  consumed: number;
  operations: Pick<OperationTrace, 'role' | 'status' | 'durationMs' | 'cause'>[];
};

// Versioned PoC profile: sensitive financial amounts and purchase structure
// require corroboration. Sensitivity is not used as a proxy for materiality.
export const RECONCILIATION_PROFILE = { version: 'poc-material-1', fields: ['declared_monthly_income', 'available_savings', 'monthly_debt', 'buyer_count'] } as const;
export class MultipassInterpreter implements Interpreter {
  constructor(private transport: FakeTransport, private onDiagnostic?: (diagnostic: MultipassDiagnostic) => void) {}
  async interpret(input: Parameters<Interpreter['interpret']>[0]) {
    const historical = input.caseSnapshot.assertions;
    // Case identity is intrinsic to the case. Other identities only come from
    // existing, non-rejected case assertions; no participants are invented.
    const subjects: SubjectRef[] = [{ scope: 'case', id: input.caseSnapshot.caseId }];
    for (const assertion of historical) if (assertion.reviewStatus !== 'rejected' && validateAssertions([assertion], input.messages, input.factSchema).ok && !subjects.some(s => s.scope === assertion.subjectRef.scope && s.id === assertion.subjectRef.id)) subjects.push(assertion.subjectRef);
    const snapshot = { caseId: input.caseSnapshot.caseId, messages: input.messages, factSchema: input.factSchema, agentProfile: input.agentProfile, knownSubjects: subjects, historicalAssertions: historical, historicalBlockers: input.caseSnapshot.blockers, materialFieldIds: RECONCILIATION_PROFILE.fields.filter(id => input.factSchema.fields.some(f => f.id === id)) };
    try {
      const { result, trace } = await runPipeline({ runId: randomUUID(), snapshot, transport: this.transport, instructionVersion: PROMPT_VERSION });
      try {
        this.onDiagnostic?.({ finalStatus: result.status, failureCode: result.status === 'failed' ? result.code : null, consumed: trace.consumed, operations: trace.operations.map(({ role, status, durationMs, cause }) => ({ role, status, durationMs, ...(cause && { cause }) })) });
      } catch { /* Diagnostics must not alter interpretation. */ }
      if (result.status === 'human_review_required') return failure('MODEL_OUTPUT_INVALID', 'La interpretación requiere revisión humana');
      if (result.status === 'failed') {
        const provider = trace.operations.some(o => ['error', 'timeout', 'cancelled'].includes(o.status));
        return failure(provider ? 'MODEL_UNAVAILABLE' : 'MODEL_OUTPUT_INVALID', provider ? 'No se pudo completar la interpretación' : 'La interpretación no superó la validación', provider);
      }
      return validateInterpretation(result.interpretation, input);
    } catch { return failure('MODEL_UNAVAILABLE', 'No se pudo completar la interpretación', true); }
  }
}

