import type { Message } from '../../../contracts';
import { OccurrenceRefSchema, type OccurrenceRef } from './contracts';

function isBoundary(text: string, position: number): boolean {
  const previous = text.charCodeAt(position - 1);
  const next = text.charCodeAt(position);
  return !(previous >= 0xd800 && previous <= 0xdbff && next >= 0xdc00 && next <= 0xdfff);
}

export function validateOccurrence(value: OccurrenceRef, messages: Message[]): boolean {
  const parsed = OccurrenceRefSchema.safeParse(value);
  if (!parsed.success) return false;
  const { messageId, statementSpan: statement, focusSpan: focus } = parsed.data;
  const matches = messages.filter(m => m.messageId === messageId);
  if (matches.length !== 1) return false;
  const message = matches[0];
  if (message.role !== 'customer' || message.content.type !== 'text') return false;
  const text = message.content.text;
  const valid = (span: typeof statement) => span.end <= text.length && isBoundary(text, span.start) && isBoundary(text, span.end) && text.slice(span.start, span.end) === span.text;
  return valid(statement) && (!focus || (focus.start >= statement.start && focus.end <= statement.end && valid(focus)));
}

import type { FactSchema, FactAssertion } from '../../../contracts';
import { ClaimCandidateSchema, type ClaimCandidate } from './contracts';

export function validateCandidate(candidate: ClaimCandidate, schema: FactSchema, messages: Message[], assertions: FactAssertion[] = []): boolean {
  const parsed = ClaimCandidateSchema.safeParse(candidate);
  if (!parsed.success || !validateOccurrence(candidate.occurrence, messages)) return false;
  const field = schema.fields.find(f => f.id === candidate.fieldId);
  if (!field || !field.scopes.includes(candidate.subjectRef.scope) || (candidate.unit !== undefined && !field.units.includes(candidate.unit))) return false;
  const correction = candidate.correction;
  if (candidate.occurrence.previousAssertionId && (!correction || correction.previousAssertionId !== candidate.occurrence.previousAssertionId)) return false;
  if (correction) {
    const matches = assertions.filter(a => a.assertionId === correction.previousAssertionId);
    if (matches.length !== 1) return false;
    const prior = matches[0];
    const currentMessage = messages.find(m => m.messageId === candidate.occurrence.messageId);
    if (!currentMessage || Date.parse(prior.observedAt) > Date.parse(currentMessage.occurredAt) || prior.evidenceRefs.some(e => e.messageId === candidate.occurrence.messageId)) return false;
    if (prior.fieldId !== candidate.fieldId || prior.reviewStatus === 'rejected' || prior.subjectRef.scope !== candidate.subjectRef.scope || prior.subjectRef.id !== candidate.subjectRef.id) return false;
    if (correction.dimension !== 'period' && candidate.period !== undefined && prior.period !== candidate.period) return false;
    if (correction.dimension !== 'unit' && candidate.unit !== undefined && prior.unit !== candidate.unit) return false;
    if (correction.dimension === 'incomeBasis' && (!candidate.incomeBasis || candidate.value !== undefined)) return false;
    if (correction.dimension === 'value' && candidate.value === undefined) return false;
    if (correction.dimension === 'period' && candidate.period === undefined) return false;
    if (correction.dimension === 'unit' && candidate.unit === undefined) return false;
  }
  const value = candidate.value;
  if (value === undefined && candidate.precision !== 'ambiguous' && !candidate.correction) return false;
  if (value !== undefined) {
    const range = typeof value === 'object' && !Array.isArray(value);
    const valid = field.type === 'money' || field.type === 'range' ? typeof value === 'number' || range : field.type === 'number' ? typeof value === 'number' : field.type === 'boolean' ? typeof value === 'boolean' : field.type === 'collection' ? Array.isArray(value) : typeof value === 'string';
    if (!valid || (field.type === 'enum' && (typeof value !== 'string' || !field.enumOptions.includes(value)))) return false;
    const numbers = typeof value === 'number' ? [value] : range ? [value.min, value.max] : [];
    const constraints = field.structuralValidation;
    if (numbers.some(n => (constraints?.min !== undefined && n < constraints.min) || (constraints?.max !== undefined && n > constraints.max) || (constraints?.integer && !Number.isInteger(n)))) return false;
  }
  return validateEvidenceRefs(candidate, messages);
}

export function validateEvidenceRefs(candidate: ClaimCandidate, messages: Message[]): boolean {
  return candidate.evidenceRefs.every(ref => {
    const matching = messages.filter(m => m.messageId === ref.messageId);
    if (matching.length !== 1 || ref.messageId !== candidate.occurrence.messageId) return false;
    const m = matching[0];
    if (m.role !== 'customer' || m.content.type !== 'text') return false;
    if (ref.start !== undefined && ref.end !== undefined) return ref.end <= m.content.text.length && isBoundary(m.content.text, ref.start) && isBoundary(m.content.text, ref.end) && (!ref.quote || m.content.text.slice(ref.start, ref.end) === ref.quote);
    return !ref.quote || m.content.text.includes(ref.quote);
  });
}
import type { FactAssertion, FactSchema, Message } from '../../../contracts';
import { ClaimCandidateSchema, type ClaimCandidate, type ClaimGroup } from './contracts';
import { validateCandidate } from './evidence';
import { occurrenceKey } from './alignment';

type GroupContext = { factSchema: FactSchema; assertions: FactAssertion[]; caseId?: string };
type Diagnostic = { candidateId: string; code: 'invalid_candidate' | 'missing_focus' | 'ambiguous_occurrence' | 'duplicate_candidate' | 'duplicate_extractor' | 'subject_unverified' | 'subject_disagreement' };

export function groupClaims(candidates: ClaimCandidate[], messages: Message[], context: GroupContext): { groups: ClaimGroup[]; rejected: ClaimCandidate[]; diagnostics: Diagnostic[] } {
  const groups = new Map<string, ClaimGroup>();
  const rejected: ClaimCandidate[] = [];
  const diagnostics: Diagnostic[] = [];
  const ids = new Set<string>();
  const conflicted = new Set<string>();
  const sorted = [...candidates].sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b), 'en'));
  // Only independently validated focuses may influence alignment.
  const textual = sorted.flatMap(candidate => {
    if (!ClaimCandidateSchema.safeParse(candidate).success || !validateCandidate(candidate, context.factSchema, messages, context.assertions) || (candidate.subjectRef.scope === 'case' && context.caseId !== undefined && candidate.subjectRef.id !== context.caseId)) return [];
    const message = messages.find(m => m.messageId === candidate.occurrence.messageId);
    if (!message || message.content.type !== 'text') return [];
    const result = occurrenceKey(candidate.fieldId, candidate.occurrence, message.content.text);
    if (!result.key || result.numeric) return [];
    const focus = candidate.occurrence.focusSpan!;
    return [{ fieldId: candidate.fieldId, messageId: candidate.occurrence.messageId, start: focus.start, end: focus.end, extractorId: candidate.extractorId }];
  });
  for (const candidate of sorted) {
    const reject = (code: Diagnostic['code']) => { rejected.push(candidate); diagnostics.push({ candidateId: candidate.candidateId, code }); };
    if (!ClaimCandidateSchema.safeParse(candidate).success || !validateCandidate(candidate, context.factSchema, messages, context.assertions) || (candidate.subjectRef.scope === 'case' && context.caseId !== undefined && candidate.subjectRef.id !== context.caseId)) { reject('invalid_candidate'); continue; }
    if (ids.has(candidate.candidateId)) { reject('duplicate_candidate'); continue; }
    ids.add(candidate.candidateId);
    const message = messages.find(m => m.messageId === candidate.occurrence.messageId)!;
    if (message.content.type !== 'text') { reject('invalid_candidate'); continue; }
    const alignment = occurrenceKey(candidate.fieldId, candidate.occurrence, message.content.text);
    let key = alignment.key;
    if (!key) { reject(alignment.reason ?? 'missing_focus'); continue; }
    if (!alignment.numeric) {
      const focus = candidate.occurrence.focusSpan!;
      const peers = textual.filter(p => p.messageId === candidate.occurrence.messageId && p.fieldId === candidate.fieldId);
      const minimal = peers.filter(p => !peers.some(q => q.start >= p.start && q.end <= p.end && (q.start > p.start || q.end < p.end)));
      const overlaps = new Map(minimal.filter(p => p.start < focus.end && p.end > focus.start).map(p => [JSON.stringify([p.start, p.end]), p]));
      let anchor: { start: number; end: number };
      if (overlaps.size === 1) {
        anchor = [...overlaps.values()][0];
        if (anchor.start < focus.start || anchor.end > focus.end) { reject('ambiguous_occurrence'); continue; }
      } else if (overlaps.size === 2) {
        const [a, b] = [...overlaps.values()];
        const related = minimal.filter(p => (p.start < a.end && p.end > a.start) || (p.start < b.end && p.end > b.start));
        const uniqueSpans = new Set(related.map(p => JSON.stringify([p.start, p.end])));
        const aExtractors = new Set(related.filter(p => p.start === a.start && p.end === a.end).map(p => p.extractorId));
        const bExtractors = new Set(related.filter(p => p.start === b.start && p.end === b.end).map(p => p.extractorId));
        if (uniqueSpans.size !== 2 || a.end <= b.start || b.end <= a.start || [...aExtractors].some(id => bExtractors.has(id))) { reject('ambiguous_occurrence'); continue; }
        anchor = { start: Math.max(a.start, b.start), end: Math.min(a.end, b.end) };
      } else { reject('ambiguous_occurrence'); continue; }
      key = JSON.stringify([candidate.occurrence.messageId, candidate.fieldId, anchor.start, anchor.end]);
    }
    const group = groups.get(key);
    const extractorKey = JSON.stringify([key, candidate.extractorId]);
    if (conflicted.has(extractorKey)) { reject('duplicate_extractor'); continue; }
    const duplicate = group?.candidates.find(c => c.extractorId === candidate.extractorId);
    if (duplicate && group) {
      const { candidateId: ignoredFirst, ...first } = duplicate;
      const { candidateId: ignoredSecond, ...second } = candidate;
      void ignoredFirst; void ignoredSecond;
      if (JSON.stringify(first) !== JSON.stringify(second)) {
        group.candidates = group.candidates.filter(c => c !== duplicate);
        rejected.push(duplicate);
        diagnostics.push({ candidateId: duplicate.candidateId, code: 'duplicate_extractor' });
        conflicted.add(extractorKey);
        if (!group.candidates.length) groups.delete(key);
        else group.occurrence = group.candidates[0].occurrence;
      }
      reject('duplicate_extractor'); continue;
    }
    if (!context.assertions.some(a => a.subjectRef.scope === candidate.subjectRef.scope && a.subjectRef.id === candidate.subjectRef.id) && !(candidate.subjectRef.scope === 'case' && candidate.subjectRef.id === context.caseId)) diagnostics.push({ candidateId: candidate.candidateId, code: 'subject_unverified' });
    if (group && group.candidates.some(c => c.subjectRef.scope !== candidate.subjectRef.scope || c.subjectRef.id !== candidate.subjectRef.id)) diagnostics.push({ candidateId: candidate.candidateId, code: 'subject_disagreement' });
    if (group) group.candidates.push(candidate);
    else groups.set(key, { groupId: key, fieldId: candidate.fieldId, occurrence: candidate.occurrence, semanticAtomicity: 'context_review_required', candidates: [candidate] });
  }
  return { groups: [...groups.values()].sort((a, b) => {
    const x = JSON.parse(a.groupId) as [string, string, number, number];
    const y = JSON.parse(b.groupId) as [string, string, number, number];
    return x[0].localeCompare(y[0], 'en') || x[1].localeCompare(y[1], 'en') || x[2] - y[2] || x[3] - y[3];
  }), rejected, diagnostics };
}
