const r=await tools.exec_command({cmd:"cat > tests/evaluation/f02-analysis-temporary.test.ts <<'EOF'
import { it } from 'vitest';
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { MultipassInterpreter, type MultipassDiagnostic } from '../../src/adapters/ai/multipass/interpreter';
import { demoBundle } from '../../src/config';
import { fixture, seed, type Id } from './f02-fixtures';
import type { Message } from '../../src/contracts';

it('replays captured single-stage multipass outputs offline for diagnosis', async () => {
  const dir='.eval-results/f02-24-20261115-multipass';
  const records=readFileSync('datasets/f01/v1/development.jsonl','utf8').trim().split('\n').map(line=>JSON.parse(line) as {id:string;messages:Message[]});
  const rows:unknown[]=[];
  for (const file of readdirSync(dir)) {
    const report=JSON.parse(readFileSync(`${dir}/${file}`,'utf8'));
    for (const row of report.runs) {
      const id:string=row.scenario??row.id;
      if (id==='C01'||id.includes('amount_correction')||id.includes('basis_correction')) continue;
      const record=records.find(x=>x.id===id);
      const fx=record ? {name:id,messages:record.messages} : fixture(id as Id);
      const snapshot=seed(fx.name,structuredClone(fx.messages));
      const calls=(row.calls as {index:number;kind:string;status:string;output?:unknown}[]).filter(c=>c.kind.startsWith('multipass_')).sort((a,b)=>a.index-b.index);
      const queues=new Map<string,typeof calls>();
      for(const c of calls){const role=c.kind.slice('multipass_'.length);const q=queues.get(role)??[];q.push(c);queues.set(role,q);}
      let diagnostic:MultipassDiagnostic|undefined;
      const interpreter=new MultipassInterpreter({execute:async request=>{const c=queues.get(request.role)?.shift();if(!c||c.status!=='response')throw Error('captured call missing');return structuredClone(c.output);}},d=>{diagnostic=d;},true);
      const result=await interpreter.interpret({caseSnapshot:snapshot,messages:snapshot.messages,factSchema:demoBundle.factSchema,agentProfile:demoBundle.agentProfile});
      rows.push({id,originalErrors:row.observed.errors,replay:result.ok?'complete':result.error.message,diagnostic});
    }
  }
  writeFileSync('/private/tmp/libeen-f02-replay-diagnostic.json',JSON.stringify(rows,null,2));
});
EOF
