const xs=require('/private/tmp/libeen-f02-replay-diagnostic.json');const counts={};for(const x of xs){const ds=x.diagnostic?.reviewDetails?.attributionDiagnostics?.filter(z=>z.status==='rejected')||[];if(!ds.length)continue;const input=x.s2Input,out=x.s2Output;const issues={};for(const d of ds){const g=input.groups.find(g=>g.groupId===d.groupId),c=g.candidates.find(c=>c.candidateId===d.candidateId),r=out.reviews.find(r=>r.groupId===d.groupId&&r.candidateId===d.candidateId),a=r?.subjectAttribution,m=input.snapshot.messages.find(m=>m.messageId===c.occurrence.messageId),st=c.occurrence.statementSpan;let why=[];if(!a)why.push('no_attribution');else{const expected=c.subjectRef.scope==='case'?'case':c.subjectRef.scope==='buying_unit'?'buying_unit':'local_speaker';if(a.kind!==expected)why.push('kind_mismatch');if(a.messageId!==c.occurrence.messageId)why.push('message_mismatch');if(r.atomicity!=='atomic'||r.support!=='supported')why.push('not_supported_atomic');for(const ref of a.evidenceRefs||[]){const start=ref.start??m.content.text.indexOf(ref.quote),end=ref.end??start+ref.quote.length;if(start<st.start||end>st.end)why.push('outside_statement');if(m.content.text.slice(start,end)!==ref.quote)why.push('offset_or_quote_mismatch');}}if(!why.length)why.push('group_rejected_or_other');for(const v of new Set(why)){issues[v]=(issues[v]||0)+1;counts[v]=(counts[v]||0)+1;}}console.log(JSON.stringify({id:x.id,rejected:ds.length,issues}));}console.log(JSON.stringify({candidateIssueCounts:counts}));
